import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    record Email(String value) {
        Email {
            throw new UnsupportedOperationException("TODO: refuse null, strip, lower-case with Locale.ROOT, require exactly one @ with text on both sides");
        }
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("two spellings of one address are equal records", () -> {
            eq(new Email("  Ana@X.io "), new Email("ana@x.io"));
