// ─────────────────────────────────────────────────────────────────────────
//  01 · normalize in the constructor★★☆
//  concepts: compact canonical constructor · record equals compares fields · accessor overrides
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    record Email(String value) {
        Email {
            if (value == null) throw new IllegalArgumentException("invalid email");
            value = value.strip().toLowerCase(Locale.ROOT);
            int at = value.indexOf('@');
            if (at <= 0 || at != value.lastIndexOf('@') || at == value.length() - 1) throw new IllegalArgumentException("invalid email");
        }
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("two spellings of one address are equal records", () -> {
            eq(new Email("  Ana@X.io "), new Email("ana@x.io"));
        });
        test("a set of users counts one address once", () -> {
            eq(new HashSet<>(List.of(new Email("Ana@X.io"), new Email("ana@x.io"), new Email("bo@x.io"))).size(), 2);
        });
        test("toString and the accessor show the stored, cleaned value", () -> {
            var e = new Email(" Bo@Example.COM");
            eq(List.of(e.toString(), e.value()), List.of("Email[value=bo@example.com]", "bo@example.com"));
        });
        test("null and blank are refused", () -> {
            raises(IllegalArgumentException.class, () -> new Email(null), "invalid email");
            raises(IllegalArgumentException.class, () -> new Email("   "), "invalid email");
        });
        test("exactly one @ with text on both sides (boundary)", () -> {
            raises(IllegalArgumentException.class, () -> new Email("@x.io"), "invalid email");
            raises(IllegalArgumentException.class, () -> new Email("ana@"), "invalid email");
            raises(IllegalArgumentException.class, () -> new Email("a@b@c.io"), "invalid email");
            eq(new Email("a@b").value(), "a@b");
        });
        test("upper-case I lower-cases to a plain i", () -> {
            eq(new Email("IVO@X.IO").value(), "ivo@x.io");
        });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

exercises.explanation:
Reassign the parameter inside the compact constructor; the field is assigned from it when the constructor ends:

```java
record Email(String value) {
    Email {
        if (value == null) throw new IllegalArgumentException("invalid email");
        value = value.strip().toLowerCase(Locale.ROOT);
        int at = value.indexOf('@');
        if (at <= 0 || at != value.lastIndexOf('@') || at == value.length() - 1) throw new IllegalArgumentException("invalid email");
    }
}
```

The tests catch the plausible wrong placements. Lower-casing in an overridden `value()` instead of the constructor leaves the raw field in place, so the set test still counts two users and `toString` prints the original spelling. Checking `contains("@")` rather than exactly one `@` with text on both sides lets `a@b@c.io` and `@x.io` through (the boundary test). Calling `toLowerCase()` with no locale works on this machine but turns `I` into a dotless `ı` under a Turkish default locale, which is why the spec names `Locale.ROOT`.

