// ─────────────────────────────────────────────────────────────────────────
//  02 · defensive copy of a list★★☆
//  concepts: shallow immutability · List.copyOf versus unmodifiableList · wither methods
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    record Order(String id, List<String> lines) {
        Order {
            throw new UnsupportedOperationException("TODO: store an independent, unmodifiable copy of lines");
        }

        Order withLine(String line) {
            throw new UnsupportedOperationException("TODO: a new order with the line appended");
        }
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("changing the source list later does not change the order", () -> {
            var src = new ArrayList<>(List.of("tea"));
            var order = new Order("o-1", src);
            src.add("cake");
            eq(order.lines(), List.of("tea"));
        });
        test("the lines cannot be changed through the accessor", () -> {
            var order = new Order("o-1", new ArrayList<>(List.of("tea")));
            raises(UnsupportedOperationException.class, () -> order.lines().add("cake"));
        });
        test("withLine returns a new order and leaves the original alone", () -> {
            var one = new Order("o-1", List.of("tea"));
            var two = one.withLine("cake");
            eq(List.of(one.lines(), two.lines()), List.of(List.of("tea"), List.of("tea", "cake")));
        });
        test("orders with the same lines are equal whatever list they came from", () -> {
            eq(new Order("o-1", new ArrayList<>(List.of("tea", "cake"))), new Order("o-1", List.of("tea", "cake")));
        });
        test("a null line is refused", () -> {
            raises(NullPointerException.class, () -> new Order("o-1", Arrays.asList("tea", null)));
        });
        test("an order with no lines is allowed and can grow (boundary)", () -> {
            eq(new Order("o-2", List.of()).withLine("tea").lines(), List.of("tea"));
        });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

