// ─────────────────────────────────────────────────────────────────────────
//  03 · money record and scale★★☆
//  concepts: BigDecimal.equals compares scale · setScale in the compact constructor · UNNECESSARY
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.math.*;
import java.util.*;

class Exercise {

    record Money(BigDecimal amount, String currency) {
        Money {
            amount = amount.setScale(2, RoundingMode.UNNECESSARY);
            if (currency == null || !currency.matches("[A-Za-z]{3}")) throw new IllegalArgumentException("bad currency");
            currency = currency.toUpperCase(Locale.ROOT);
        }

        Money plus(Money other) {
            if (!currency.equals(other.currency())) throw new IllegalArgumentException("currency mismatch");
            return new Money(amount.add(other.amount()), currency);
        }
    }

    static Money eur(String amount) { return new Money(new BigDecimal(amount), "EUR"); }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("1.5 and 1.50 are the same money", () -> {
            eq(new Money(new BigDecimal("1.5"), "eur"), new Money(new BigDecimal("1.50"), "EUR"));
        });
        test("equal amounts land in one HashSet bucket", () -> {
            eq(new HashSet<>(List.of(eur("1.5"), eur("1.50"), eur("1.500"), eur("2"))).size(), 2);
        });
        test("toString shows two decimals, never an exponent", () -> {
            eq(List.of(eur("10").toString(), eur("0").toString()), List.of("Money[amount=10.00, currency=EUR]", "Money[amount=0.00, currency=EUR]"));
        });
        test("a third non-zero decimal is refused, not rounded", () -> {
            raises(ArithmeticException.class, () -> eur("1.505"));
        });
        test("currency is three letters, stored upper-case", () -> {
            raises(IllegalArgumentException.class, () -> new Money(BigDecimal.ONE, "EURO"), "bad currency");
            eq(new Money(BigDecimal.ONE, "usd").currency(), "USD");
        });
        test("plus adds the same currency and refuses another (boundary)", () -> {
            eq(eur("0.10").plus(eur("0.2")), eur("0.30"));
            raises(IllegalArgumentException.class, () -> eur("1").plus(new Money(BigDecimal.ONE, "USD")), "currency mismatch");
        });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

exercises.explanation:
Fix the scale once, in the constructor, with a rounding mode that refuses to round:

```java
Money {
    amount = amount.setScale(2, RoundingMode.UNNECESSARY);
    if (currency == null || !currency.matches("[A-Za-z]{3}")) throw new IllegalArgumentException("bad currency");
    currency = currency.toUpperCase(Locale.ROOT);
}
```

`UNNECESSARY` throws `ArithmeticException` when the value would change, so `1.505` is refused while `1.500` is accepted. The tests catch the plausible wrong fixes. `stripTrailingZeros` makes `1.5` and `1.50` equal but prints `10.00` as `1E+1` (the toString test). Rounding with `HALF_EVEN` instead of `UNNECESSARY` silently turns `1.505` into `1.50` (the refusal test). Overriding `equals` with `compareTo` but leaving `hashCode` alone breaks the `HashSet` test, because equal values land in different buckets.

