//  04 · the equals a record writes★★★
//  concepts: Double.compare semantics · NaN equals NaN · 0.0 versus -0.0 · hashCode agrees
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    /** The original: its equals and hashCode are the contract to keep. */
    record Reading(String sensor, double value) {}


    static final class ReadingClass {
        final String sensor;
        final double value;
        ReadingClass(String sensor, double value) { this.sensor = sensor; this.value = value; }

        @Override public boolean equals(Object o) {
            throw new UnsupportedOperationException("TODO: equal exactly when the record would be");
        }

        @Override public int hashCode() {
            throw new UnsupportedOperationException("TODO: agree with equals");
        }
    }

    static boolean sameAsRecord(String s1, double v1, String s2, double v2) {
        return new ReadingClass(s1, v1).equals(new ReadingClass(s2, v2)) == new Reading(s1, v1).equals(new Reading(s2, v2));
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("NaN readings are equal, as in the record", () -> {
            eq(List.of(new ReadingClass("t1", Double.NaN).equals(new ReadingClass("t1", Double.NaN)), new Reading("t1", Double.NaN).equals(new Reading("t1", Double.NaN))), List.of(true, true));
        });
        test("0.0 and -0.0 are different readings, as in the record", () -> {
            eq(List.of(new ReadingClass("t1", 0.0).equals(new ReadingClass("t1", -0.0)), new Reading("t1", 0.0).equals(new Reading("t1", -0.0))), List.of(false, false));
        });
        test("a set of readings keeps one NaN per sensor", () -> {
            var set = new HashSet<>(List.of(new ReadingClass("t1", Double.NaN), new ReadingClass("t1", Double.NaN), new ReadingClass("t2", 1.5)));
            eq(set.size(), 2);
        });
        test("equals agrees with the record on ordinary values and on null sensors", () -> {
            eq(List.of(sameAsRecord("t1", 1.5, "t1", 1.5), sameAsRecord("t1", 1.5, "t2", 1.5), sameAsRecord(null, 2.0, null, 2.0), sameAsRecord(null, 2.0, "t1", 2.0)), List.of(true, true, true, true));
        });
        test("equal readings have equal hash codes, NaN included", () -> {
            eq(List.of(new ReadingClass("t1", Double.NaN).hashCode() == new ReadingClass("t1", Double.NaN).hashCode(), new ReadingClass(null, 2.5).hashCode() == new ReadingClass(null, 2.5).hashCode()), List.of(true, true));
        });
        test("null and other classes are never equal (boundary)", () -> {
            var r = new ReadingClass("t1", 1.0);
            eq(List.of(r.equals(null), r.equals(new Reading("t1", 1.0)), r.equals(r)), List.of(false, false, true));
        });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

