// ─────────────────────────────────────────────────────────────────────────
//  05 · a record as a map key★★☆
//  concepts: composite keys · string concatenation collisions · records as map keys
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    record Sale(String customer, String day, long cents) {}
    record DayKey(String customer, String day) {}


    static Map<DayKey, Long> revenueByCustomerAndDay(List<Sale> sales) {
        var out = new TreeMap<DayKey, Long>(Comparator.comparing(DayKey::customer).thenComparing(DayKey::day));
        for (var s : sales) out.merge(new DayKey(s.customer(), s.day()), s.cents(), Long::sum);
        return out;
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("sums per customer and day", () -> {
            var r = revenueByCustomerAndDay(List.of(new Sale("ana", "2026-03-07", 100), new Sale("ana", "2026-03-07", 25), new Sale("bo", "2026-03-07", 10)));
            eq(r, Map.of(new DayKey("ana", "2026-03-07"), 125L, new DayKey("bo", "2026-03-07"), 10L));
        });
        test("customer ab on day c is not customer a on day bc", () -> {
            var r = revenueByCustomerAndDay(List.of(new Sale("ab", "c", 100), new Sale("a", "bc", 50), new Sale("ab", "c", 25)));
            eq(r.toString(), "{DayKey[customer=a, day=bc]=50, DayKey[customer=ab, day=c]=125}");
        });
        test("a separator inside a value does not merge two keys", () -> {
            var r = revenueByCustomerAndDay(List.of(new Sale("a|b", "c", 1), new Sale("a", "b|c", 2)));
            eq(r.size(), 2);
        });
        test("two days of one customer stay apart, ordered by day", () -> {
            var r = revenueByCustomerAndDay(List.of(new Sale("ana", "2026-03-08", 5), new Sale("ana", "2026-03-07", 7)));
            eq(new ArrayList<>(r.values()), List.of(7L, 5L));
        });
        test("an empty list gives an empty map (boundary)", () -> {
            eq(revenueByCustomerAndDay(List.of()), Map.of());
        });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

exercises.explanation:
Key on the record and let `merge` add the cents:

```java
var out = new TreeMap<DayKey, Long>(Comparator.comparing(DayKey::customer).thenComparing(DayKey::day));
for (var s : sales) out.merge(new DayKey(s.customer(), s.day()), s.cents(), Long::sum);
return out;
```

The tests catch the plausible string keys. `customer + day` merges `ab`/`c` with `a`/`bc` (the collision test). `customer + "|" + day` survives that case but merges `a|b`/`c` with `a`/`b|c` (the separator test), and a customer id may contain any character. Ordering with a comparator on `customer` alone, rather than `thenComparing(day)`, makes the `TreeMap` treat two days of one customer as the same key, so the second day's sales vanish into the first (the two-days test).

